-- Additive two-person journey archive. Room/person capability checks match the existing notebook.
begin;
create table if not exists youqi_private.journey_books(room_id uuid primary key references youqi_private.countdowns(id) on delete cascade,created_at timestamptz not null default now(),revision bigint not null default 0);
alter table youqi_private.journey_books add column if not exists revision bigint not null default 0;
create table if not exists youqi_private.journey_defaults(city_id text primary key,feature jsonb not null);
create table if not exists youqi_private.journey_cities(
 room_id uuid not null references youqi_private.journey_books(room_id) on delete cascade,city_id text not null,name text not null check(char_length(name) between 1 and 80),country text not null check(country~'^[A-Z]{3}$'),region text not null default '',longitude double precision not null check(longitude between -180 and 180),latitude double precision not null check(latitude between -90 and 90),geometry jsonb not null,visited boolean not null default true,updated_at timestamptz not null default now(),primary key(room_id,city_id));
create table if not exists youqi_private.journey_media(
 seq bigint generated always as identity unique,id uuid primary key,room_id uuid not null,city_id text not null,author_id uuid not null,provider text not null check(provider in ('supabase','r2')),object_key text not null unique,thumb_key text not null unique,kind text not null check(kind in ('image','video')),mime text not null check(mime in ('image/jpeg','video/mp4','video/webm')),bytes bigint not null check(bytes between 1 and 40000000),thumb_bytes integer not null check(thumb_bytes between 1 and 180000),width integer not null check(width between 1 and 20000),height integer not null check(height between 1 and 20000),duration double precision not null default 0 check(duration between 0 and 600),title text not null default '' check(char_length(title)<=80),body text not null default '' check(char_length(body)<=2000),taken_on date,state text not null default 'pending' check(state in ('pending','ready','deleted')),version bigint not null default 1,created_at timestamptz not null default now(),ready_at timestamptz,foreign key(room_id,city_id) references youqi_private.journey_cities(room_id,city_id),foreign key(room_id,author_id) references youqi_private.letter_people(room_id,id));
create index if not exists journey_media_city_page on youqi_private.journey_media(room_id,city_id,seq desc) where state='ready';
create index if not exists journey_media_room_storage on youqi_private.journey_media(provider,room_id,state);
create index if not exists journey_media_author_day on youqi_private.journey_media(author_id,created_at desc);
create table if not exists youqi_private.journey_comments(seq bigint generated always as identity unique,id uuid primary key,room_id uuid not null,media_id uuid not null references youqi_private.journey_media(id),author_id uuid not null,body text not null check(char_length(btrim(body)) between 1 and 1000),created_at timestamptz not null default now(),foreign key(room_id,author_id) references youqi_private.letter_people(room_id,id));
create table if not exists youqi_private.journey_geocache(key text primary key,data jsonb not null default '[]',created_at timestamptz not null default clock_timestamp());
alter table youqi_private.journey_geocache enable row level security;revoke all on youqi_private.journey_geocache from public,anon,authenticated;
create index if not exists journey_comments_page on youqi_private.journey_comments(room_id,media_id,seq desc);
create index if not exists journey_comments_author on youqi_private.journey_comments(author_id,created_at desc);
alter table youqi_private.journey_books enable row level security;alter table youqi_private.journey_defaults enable row level security;alter table youqi_private.journey_cities enable row level security;alter table youqi_private.journey_media enable row level security;alter table youqi_private.journey_comments enable row level security;
revoke all on youqi_private.journey_books,youqi_private.journey_defaults,youqi_private.journey_cities,youqi_private.journey_media,youqi_private.journey_comments from public,anon,authenticated;
revoke all on sequence youqi_private.journey_media_seq_seq,youqi_private.journey_comments_seq_seq from public,anon,authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('youqi-journey','youqi-journey',false,40000000,array['image/jpeg','video/mp4','video/webm']) on conflict(id) do nothing;
